'use client';
import {useEffect,useMemo,useState} from 'react';
import {CheckCircle2,Download,MapPin,Paperclip,XCircle} from 'lucide-react';
import {useParams} from 'next/navigation';

type Job={recipient:{name:string|null;email:string|null};shift:{id:string;name:string;status:string;date:string|null;start:string|null;finish:string|null;scope:string|null;siteContact:string|null;project:string|null;client:string|null;site:string|null;location:{address:string|null;lat:number|null;lng:number|null}|null};documents:Array<{id:string;title:string;fileName:string;category:string;url:string}>;responses:Array<{kind:string;payload:Record<string,unknown>|null;createdAt:string}>};
const date=(v:string|null)=>v?new Date(v+'T12:00:00Z').toLocaleDateString('en-AU',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}):'Date not set';
const time=(a:string|null,b:string|null)=>a&&b?a+'–'+b:a||b||'Time not set';

export default function ExternalJobPage(){
 const params=useParams<{token:string}>(),token=String(params?.token||''),[data,setData]=useState<Job|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[note,setNote]=useState(''),[operator,setOperator]=useState(''),[plant,setPlant]=useState('');
 const load=async()=>{setError('');try{const r=await fetch('/api/external/job?token='+encodeURIComponent(token),{cache:'no-store'}),b=await r.json();if(!r.ok)throw new Error(b.error||'This job link is unavailable.');setData(b);}catch(e){setError(e instanceof Error?e.message:'This job link is unavailable.');}};
 useEffect(()=>{if(token)void load();},[token]); // eslint-disable-line react-hooks/exhaustive-deps
 const respond=async(action:string)=>{setBusy(true);setError('');try{const f=new FormData();f.set('token',token);f.set('action',action);f.set('note',note);f.set('operator',operator);f.set('plant',plant);const r=await fetch('/api/external/job',{method:'POST',body:f}),b=await r.json();if(!r.ok)throw new Error(b.error||'Unable to save your response.');setNote('');await load();}catch(e){setError(e instanceof Error?e.message:'Unable to save your response.');}finally{setBusy(false);}};
 const upload=async(file:File)=>{setBusy(true);setError('');try{const f=new FormData();f.set('token',token);f.set('file',file);const r=await fetch('/api/external/job',{method:'POST',body:f}),b=await r.json();if(!r.ok)throw new Error(b.error||'Upload failed.');await load();}catch(e){setError(e instanceof Error?e.message:'Upload failed.');}finally{setBusy(false);}};
 const directions=useMemo(()=>{const l=data?.shift.location;if(l?.lat!=null&&l.lng!=null)return 'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(l.lat+','+l.lng);const a=l?.address||data?.shift.site;return a?'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(a):null;},[data]);
 if(error&&!data)return <main className="mx-auto min-h-screen max-w-xl bg-slate-50 p-5"><div className="mt-16 rounded-2xl border bg-white p-6"><h1 className="text-xl font-bold">Job link unavailable</h1><p className="mt-2 text-sm text-slate-600">{error}</p></div></main>;
 if(!data)return <main className="grid min-h-screen place-items-center bg-slate-50"><p className="text-sm text-slate-500">Loading job…</p></main>;
 const s=data.shift,last=data.responses[0];
 return <main className="min-h-screen bg-slate-50 pb-10 text-slate-900"><header className="border-b bg-white px-4 py-4"><div className="mx-auto max-w-2xl"><p className="text-xs font-bold uppercase tracking-[.14em] text-orange-600">Infrastruct secure job link</p><h1 className="mt-1 text-xl font-bold">{s.name}</h1><p className="text-sm text-slate-500">{s.client||'Client'} · {s.project||'Project'}</p></div></header><div className="mx-auto grid max-w-2xl gap-4 p-4">
  {error&&<p role="alert" className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800">{error}</p>}
  <section className="rounded-2xl border bg-white p-5 shadow-sm"><div className="grid gap-3 sm:grid-cols-2"><div><p className="text-xs font-semibold uppercase text-slate-400">Date</p><p className="font-medium">{date(s.date)}</p></div><div><p className="text-xs font-semibold uppercase text-slate-400">Time</p><p className="font-medium">{time(s.start,s.finish)}</p></div><div className="sm:col-span-2"><p className="text-xs font-semibold uppercase text-slate-400">Scope</p><p className="whitespace-pre-wrap">{s.scope||'No scope recorded.'}</p></div></div></section>
  <section className="rounded-2xl border bg-white p-5 shadow-sm"><div className="flex items-start gap-3"><MapPin className="mt-1 size-5 shrink-0 text-orange-600"/><div className="min-w-0 flex-1"><h2 className="font-semibold">Work location</h2><p className="mt-1 text-sm text-slate-600">{s.location?.address||s.site||'Location not recorded.'}</p>{directions&&<a className="mt-3 inline-flex min-h-10 items-center rounded-lg bg-slate-950 px-4 text-sm font-medium text-white" href={directions} target="_blank" rel="noreferrer">Open directions</a>}</div></div></section>
  {s.siteContact&&<section className="rounded-2xl border bg-white p-5"><h2 className="font-semibold">Site contact</h2><p className="mt-1 text-sm text-slate-600">{s.siteContact}</p></section>}
  <section className="rounded-2xl border bg-white p-5"><h2 className="font-semibold">Job documents</h2>{data.documents.length?<ul className="mt-2 divide-y">{data.documents.map(d=><li key={d.id} className="flex items-center gap-3 py-2"><span className="min-w-0 flex-1"><span className="block truncate text-sm font-medium">{d.title}</span><span className="block text-xs text-slate-400">{d.category}</span></span><a href={d.url} className="inline-flex min-h-10 items-center gap-1 rounded-lg border px-3 text-sm"><Download className="size-4"/>Open</a></li>)}</ul>:<p className="mt-2 text-sm text-slate-500">No field-visible documents have been shared.</p>}</section>
  <section className="rounded-2xl border bg-white p-5"><h2 className="font-semibold">Confirm this job</h2>{last&&<p className="mt-1 text-sm text-slate-500">Latest response: <strong className="capitalize">{last.kind}</strong></p>}<div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-sm">Operator<input className="mt-1 min-h-11 w-full rounded-lg border px-3" value={operator} onChange={e=>setOperator(e.target.value)} placeholder="Name / operator"/></label><label className="text-sm">Plant / vehicle<input className="mt-1 min-h-11 w-full rounded-lg border px-3" value={plant} onChange={e=>setPlant(e.target.value)} placeholder="Plant no. / registration"/></label></div><label className="mt-3 block text-sm">Note<textarea className="mt-1 min-h-20 w-full rounded-lg border p-3" value={note} onChange={e=>setNote(e.target.value)} placeholder="Access, availability or other details"/></label><div className="mt-3 flex flex-wrap gap-2"><button disabled={busy} onClick={()=>void respond('accepted')} className="inline-flex min-h-11 items-center gap-2 rounded-lg bg-emerald-700 px-4 text-sm font-semibold text-white disabled:opacity-50"><CheckCircle2 className="size-4"/>Accept</button><button disabled={busy} onClick={()=>void respond('declined')} className="inline-flex min-h-11 items-center gap-2 rounded-lg border border-red-300 bg-white px-4 text-sm font-semibold text-red-700 disabled:opacity-50"><XCircle className="size-4"/>Decline</button><button disabled={busy} onClick={()=>void respond('acknowledged')} className="min-h-11 rounded-lg border px-4 text-sm font-semibold disabled:opacity-50">Acknowledge details</button>{(operator||plant)&&<button disabled={busy} onClick={()=>void respond('details')} className="min-h-11 rounded-lg border px-4 text-sm font-semibold disabled:opacity-50">Update operator / plant</button>}</div></section>
  <section className="rounded-2xl border bg-white p-5"><div className="flex items-center gap-2"><Paperclip className="size-4"/><h2 className="font-semibold">Return evidence</h2></div><p className="mt-1 text-xs text-slate-500">Upload PDF or image evidence such as a docket, delivery receipt or site photo. Maximum 20 MB.</p><input className="mt-3 block w-full text-sm" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.heic" disabled={busy} onChange={e=>{const f=e.target.files?.[0];if(f)void upload(f);}}/></section>
  <p className="px-1 text-center text-xs text-slate-400">This link is limited to this job and expires automatically.</p>
 </div></main>;
}
